  const iso = l.lang_iso;
  if (EXCL.indexOf(iso) !== -1) { continue; }
  const gl = [];
  for (const t of inScope) {
    const src = String(t.term || '').trim();
    if (!src) { continue; }
    let tgt = '';
    let tnote = '';
    for (const tr of (t.translations || [])) {
      const tiso = tr.langIso || tr.lang_iso || ISO_BY_ID[tr.langId || tr.lang_id];
      if (tiso === iso) { tgt = String(tr.translation || '').trim(); tnote = String(tr.description || '').trim(); }
    }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    gl.push({ src: src, cs: yes(t.caseSensitive !== undefined ? t.caseSensitive : t.case_sensitive), tr: translatable, fb: yes(t.forbidden), tgt: tgt, note: (tnote || String(t.description || '')).slice(0, 200) });
  }
  const rules = (RULES[iso] || []).filter(function (r) { return !r.project || (r.project === 'personality' ? isPersonality : !isPersonality); })
    .concat(GENERIC.filter(function (g) { return g.langs === '*' || g.langs.indexOf(iso) !== -1; }));
  jobs.push({ json: {
    project_id: pick.project_id, project_name: pick.project_name, run_date: pick.run_date,
    iso: iso, lang_id: l.lang_id, en_id: enLang.lang_id, lang_name: l.lang_name,
    is_personality: isPersonality, glossary: gl, rules: rules, judgement: JUDGE[iso] || '', feedback: fbFor(iso)
  } });
}
if (!jobs.length) { throw new Error('No target languages to audit in ' + pick.project_name); }
jobs.sort(function (a, b) { return a.json.lang_name < b.json.lang_name ? -1 : 1; });
return jobs;

const NL = String.fromCharCode(10);
const jobs = $('Build language jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
const pick = $("Pick today's project").first().json;
const langs = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i];
  let r = res.find(function (x) { return x.iso === j.iso; });
  if (!r) { r = { iso: j.iso, lang_name: j.lang_name, findings: [], errors: ['sub-workflow failed: ' + JSON.stringify((res[i] || {}).error || res[i] || 'no result').slice(0, 200)], strings_checked: 0, failed: true }; }
  const f = r.findings || [];
  const g = f.filter(function (x) { return x.check === 'Glossary'; }).length;
  const s = f.filter(function (x) { return x.check === 'Style'; }).length;
  const h = f.filter(function (x) { return x.severity === 'High'; }).length;
  const notChecked = r.failed || (r.strings_checked === 0);
  langs.push({ iso: j.iso, name: j.lang_name, glossary: g, style: s, high: h, strings: r.strings_checked || 0, findings: f, errors: r.errors || [], triage_ok: r.triage_ok !== false, overflow: r.overflow || 0, conflicts: r.glossary_conflicts || [], not_checked: notChecked });
}
const checked = langs.filter(function (l) { return !l.not_checked; });
const withF = checked.filter(function (l) { return l.glossary + l.style > 0; });
const clean = checked.filter(function (l) { return l.glossary + l.style === 0; });
const failed = langs.filter(function (l) { return l.not_checked; });
const noTriage = langs.filter(function (l) { return !l.not_checked && !l.triage_ok; });
const tg = langs.reduce(function (a, l) { return a + l.glossary; }, 0);
const ts = langs.reduce(function (a, l) { return a + l.style; }, 0);
const th = langs.reduce(function (a, l) { return a + l.high; }, 0);
const strings = langs.reduce(function (a, l) { return a + l.strings; }, 0);

const summary = '*Linguistic audit — ' + pick.project_name + '*  ·  ' + langs.length + ' languages  ·  all translated strings' + NL +
  '*Totals*  Glossary: ' + tg + '  ·  Style: ' + ts + '   (' + th + ' high severity)';

const d = [];
d.push('*Languages with findings (' + withF.length + ' of ' + langs.length + ')*');
for (const l of withF) { d.push('• *' + l.name + '* — Glossary: ' + l.glossary + ' · Style: ' + l.style); }
if (clean.length) { d.push(':white_check_mark: ' + clean.length + ' languages clean.'); }
if (failed.length) { d.push(':warning: Not checked: ' + failed.map(function (l) { return l.name; }).join(', ') + '.'); }
if (noTriage.length) { d.push(':warning: LLM triage unavailable, only brand/forbidden-term hits reported: ' + noTriage.map(function (l) { return l.name; }).join(', ') + '.'); }
const detail = d.join(NL);

const j = [];
j.push('h3. Linguistic audit — ' + pick.project_name + ' — ' + pick.run_date);
j.push('Scope: all translated strings (' + strings + ' strings, ' + langs.length + ' languages). Checks: glossary adherence and style-guide compliance — mechanical rules from each style guide, LLM triage of every candidate, plus an LLM style-guide review of the 20 longest strings per language. Spelling and accuracy against the English source are not checked.');
j.push('');
j.push('||Language||Strings||Glossary||Style||High||');
for (const l of langs) { j.push('|' + l.name + '|' + l.strings + '|' + (l.not_checked ? 'not checked' : l.glossary) + '|' + (l.not_checked ? '-' : l.style) + '|' + (l.not_checked ? '-' : l.high) + '|'); }
j.push('|*Total*|' + strings + '|*' + tg + '*|*' + ts + '*|*' + th + '*|');
const errs = langs.filter(function (l) { return l.errors.length; });
if (errs.length) { j.push(''); j.push('*Errors*'); for (const l of errs) { j.push('* ' + l.name + ': ' + l.errors.join('; ').slice(0, 300)); } }
const ov = langs.filter(function (l) { return l.overflow > 0; });
if (ov.length) { j.push(''); j.push('*Candidates over the per-language triage cap (not reviewed):* ' + ov.map(function (l) { return l.name + ' ' + l.overflow; }).join(', ')); }
const cf = langs.filter(function (l) { return l.conflicts.length; });
if (cf.length) { j.push(''); j.push('*Possible glossary vs style-guide conflicts (check the glossary, not the translation)*'); for (const l of cf) { for (const c of l.conflicts) { j.push('* ' + l.name + ': ' + String(c).slice(0, 250)); } } }
j.push('');
j.push('Workbook with every finding attached (one row per finding; filter by Language). Rotation: nightly on weekdays, one product per run — ' + pick.rotation_size + ' products.');

const safe = pick.project_name.replace(/[\\/:*?"<>|]/g, '-');
return [{ json: {
  project_id: pick.project_id, project_name: pick.project_name, run_date: pick.run_date,
  languages: langs.length, glossary: tg, style: ts, high: th,
  not_checked: failed.map(function (l) { return l.iso; }).join(','),
  slack_summary: summary, slack_detail: detail,
  jira_summary: 'Linguistic audit – ' + pick.project_name + ' – ' + pick.run_date,
  jira_description: j.join(NL),
  file_name: 'Linguistic audit - ' + safe + ' - ' + pick.run_date + '.xlsx',
  langs: langs
} }];

const a = $('Aggregate results').first().json;
const out = [];
let n = 0;
function base(l) { return { 'Reject? (x)': '', 'Reason (optional)': '', ID: '', Language: l.name, ISO: l.iso, Check: '', Severity: '', 'Rule / term': '', Key: '', 'Key description': '', English: '', Translation: '', Issue: '', Suggestion: '', 'Found by': '' }; }
for (const l of a.langs) {
  if (l.not_checked) { const r = base(l); r.Issue = 'NOT CHECKED \u2014 ' + (l.errors.join('; ') || 'no strings'); out.push({ json: r }); continue; }
  if (!l.findings.length) { const r = base(l); r.Issue = 'No issues found for this language (' + l.strings + ' strings checked)'; out.push({ json: r }); continue; }
  for (const f of l.findings) {
    n++;
    const r = base(l);
    r.ID = 'F' + String(n).padStart(4, '0');
    r.Check = f.check; r.Severity = f.severity; r['Rule / term'] = f.rule; r.Key = f.key; r['Key description'] = f.key_description || '';
    r.English = String(f.en || '').slice(0, 30000); r.Translation = String(f.translation || '').slice(0, 30000);
    r.Issue = f.issue; r.Suggestion = f.suggestion; r['Found by'] = f.found_by;
    out.push({ json: r });
  }
}
return out;
